let user = null, tab = 'home', planning = false, editingTemplateId = null, editingPlanDate = '', loginError = '', syncError = '', catalogError = '', templateNotice = '', isLoading = true, data = emptyData(), catalog = [...defaultCatalog], workoutName = 'Mój trening', startedAt = 0, restStartedAt = 0, timer = null, catalogSheetOpen = false, templateSheetOpen = false, draggedDraftIndex = null, editingWorkoutId = null, editingWorkoutDate = '', editingWorkoutDuration = 0, expandedWorkouts = new Set(), expandedRecordCategories = new Set(), planWeekOffset = 0, selectedPlanDate = todayIso(), templateSaveInProgress = false, lastSavedTemplateKey = '', historyExerciseFilter = '', planningPlanDate = '', templateSelectionPlanDate = '', loginAccountId = '', activeRecordHint = '', activeExerciseInfo = '', editingCatalogId = '';
function ex(name, category, kg, reps, description='', imageUrl=''){return {name,category,description,imageUrl,sets:[{kg,reps,metric:'reps'}]};}
function emptyData(){return {workouts:[],plans:{},draft:[],templates:[]};}
function demoData(){return {workouts:initialWorkouts,plans:{},draft:[],templates:[]};}
function slug(value){return value.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,48)||'cwiczenie';}
function escapeHtml(value){return String(value).replace(/[&<>"]/g,(char)=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[char]));}
function readAccounts(){try{return JSON.parse(localStorage.getItem(accountsKey)||'[]');}catch(error){return [];}}
function writeAccounts(accounts){localStorage.setItem(accountsKey,JSON.stringify(accounts));}
async function loadAccounts(){const response=await fetch('/api/accounts');if(!response.ok)throw new Error('Nie udało się pobrać kont z backendu.');const body=await response.json();const accounts=Array.isArray(body.accounts)?body.accounts:[];writeAccounts(accounts);return accounts;}
async function saveAccount(account){const response=await fetch('/api/accounts',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(account)});if(!response.ok){const body=await response.json().catch(()=>({}));throw new Error(body.error||'Nie udało się zapisać konta.');}const body=await response.json();writeAccounts(Array.isArray(body.accounts)?body.accounts:[...readAccounts(),account]);}
function accountId(name){return `local-${Date.now()}-${slug(name).slice(0,32)||'osoba'}`;}
function selectAccount(account){user=account;expandedWorkouts=new Set();localStorage.setItem(activeAccountKey,account.id);isLoading=true;syncError='';render();Promise.all([loadCatalog(),loadUserData()]).catch(()=>{syncError='Nie udało się pobrać danych z backendu. Używamy pustego widoku tej osoby.';data=emptyData();}).finally(()=>{isLoading=false;render();});}
async function authenticate(password){const response=await fetch('/api/auth',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({password})});if(!response.ok){const body=await response.json().catch(()=>({}));throw new Error(body.error||'Nie udało się potwierdzić hasła.');}loginError='';}
async function loadUserData(){const response=await fetch('/api/data',{headers:{'X-User-Id':user.id}});if(!response.ok)throw new Error('Nie udało się pobrać danych użytkownika.');const body=await response.json();data=normalizeData(body.data||emptyData());}
async function loadCatalog(){try{const response=await fetch('/api/catalog');if(!response.ok)throw new Error('Nie udało się pobrać ćwiczeń.');const body=await response.json();catalog=Array.isArray(body.catalog)&&body.catalog.length?body.catalog:defaultCatalog;catalogError='';}catch(error){catalog=[...defaultCatalog];catalogError='Nie udało się pobrać wspólnej listy ćwiczeń. Możesz korzystać z domyślnej listy.';}}
async function save(){if(!user)return;try{const response=await fetch('/api/data',{method:'PUT',headers:{'Content-Type':'application/json','X-User-Id':user.id},body:JSON.stringify(data)});if(!response.ok)throw new Error('Nie udało się zapisać danych.');syncError='';}catch(error){syncError='Nie udało się zsynchronizować danych z backendem.';}}
async function saveExercise(name, category, description='', imageUrl=''){const payload={name:name.trim(),category:category.trim(),description:description.trim(),imageUrl:imageUrl.trim()};const response=await fetch('/api/catalog',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!response.ok){const body=await response.json().catch(()=>({}));throw new Error(body.error||'Nie udało się dodać ćwiczenia.');}const body=await response.json();catalog=body.catalog;return body.exercise;}
async function updateCatalogExercise(id,payload){const response=await fetch(`/api/catalog/${encodeURIComponent(id)}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!response.ok){const body=await response.json().catch(()=>({}));throw new Error(body.error||'Nie udało się zapisać ćwiczenia.');}const body=await response.json();catalog=body.catalog;return body.exercise;}
async function deleteCatalogExercise(id){const response=await fetch(`/api/catalog/${encodeURIComponent(id)}`,{method:'DELETE'});if(!response.ok){const body=await response.json().catch(()=>({}));throw new Error(body.error||'Nie udało się usunąć ćwiczenia.');}const body=await response.json();catalog=body.catalog;}
function icon(name){const icons={play:'▶',plus:'＋',x:'×',info:'i',left:'‹',right:'›',trend:'↗',pulse:'⌁',clock:'◴',copy:'⧉',save:'✓',trash:'🗑',edit:'✎',check:'✓'};return icons[name]||'';}
function navIcon(name){return `<svg class="nav-icon" viewBox="0 0 24 24" aria-hidden="true"><use href="#icon-${name}"></use></svg>`;}
function sprite(){return `<svg class="icon-sprite" aria-hidden="true"><symbol id="icon-home" viewBox="0 0 24 24"><path d="M6.6 21h10.8a2 2 0 0 0 2-2v-6.2l1.1.9 1.4-1.7L12 3.7 2.1 12l1.4 1.7 1.1-.9V19a2 2 0 0 0 2 2Zm2.7-8.3 1.4-1.4 1.3 1.3 1.3-1.3 1.4 1.4-1.3 1.3 1.3 1.3-1.4 1.4-1.3-1.3-1.3 1.3-1.4-1.4 1.3-1.3-1.3-1.3Z"/></symbol><symbol id="icon-history" viewBox="0 0 24 24"><path d="M12 2.5a9.5 9.5 0 1 0 9.5 9.5H19a7 7 0 1 1-2.05-4.95l-2.2 2.2h6.1V3.15l-2.12 2.12A9.47 9.47 0 0 0 12 2.5Z"/><path d="M11 6.5h2v5.1l3.4 2-.95 1.75L11 12.75V6.5Z"/></symbol><symbol id="icon-plan" viewBox="0 0 24 24"><path d="M7 2h2v3h6V2h2v3h1.5A2.5 2.5 0 0 1 21 7.5v11A2.5 2.5 0 0 1 18.5 21h-13A2.5 2.5 0 0 1 3 18.5v-11A2.5 2.5 0 0 1 5.5 5H7V2Zm12 8H5v8.2c0 .44.36.8.8.8h12.4c.44 0 .8-.36.8-.8V10Z"/><path d="M7 12h3v3H7v-3Zm5 0h3v3h-3v-3Z"/></symbol><symbol id="icon-profile" viewBox="0 0 24 24"><path d="M12 12.4a4.7 4.7 0 1 0 0-9.4 4.7 4.7 0 0 0 0 9.4Zm0 2.1c-4.6 0-8.2 2.35-8.2 5.25 0 .7.55 1.25 1.25 1.25h13.9c.7 0 1.25-.55 1.25-1.25 0-2.9-3.6-5.25-8.2-5.25Z"/></symbol></svg>`;}
function normalizeData(value){const body=value&&typeof value==='object'?value:emptyData();return {workouts:Array.isArray(body.workouts)?body.workouts.map(normalizeWorkout):[],plans:body.plans&&typeof body.plans==='object'&&!Array.isArray(body.plans)?body.plans:{},draft:Array.isArray(body.draft)?body.draft.map(cloneExercise):[],templates:Array.isArray(body.templates)?body.templates.map(normalizeTemplate):[]};}
function normalizeTemplate(template){return {...template,exercises:Array.isArray(template.exercises)?template.exercises.map(cloneTemplateExercise):[]};}
function normalizeWorkout(workout){return {...workout,exercises:Array.isArray(workout.exercises)?workout.exercises.map(e=>({...e,sets:Array.isArray(e.sets)?e.sets.map(normalizeSet):[]})):[]};}
function todayIso(){return new Date().toISOString().slice(0,10);}
function parseIsoDate(date){return new Date(`${date}T00:00:00`);}
function toIsoDate(date){const copy=new Date(date);copy.setHours(0,0,0,0);return copy.toISOString().slice(0,10);}
function addDays(date,days){const copy=new Date(date);copy.setDate(copy.getDate()+days);return copy;}
function startOfWeek(date){const copy=new Date(date);const day=(copy.getDay()+6)%7;copy.setDate(copy.getDate()-day);copy.setHours(0,0,0,0);return copy;}
function formatDate(date){if(!date)return 'Brak daty';return parseIsoDate(date).toLocaleDateString('pl-PL',{day:'numeric',month:'short',year:'numeric'});}
function formatShortDate(date){return parseIsoDate(date).toLocaleDateString('pl-PL',{day:'numeric',month:'short'});}
function weekdayName(date){return parseIsoDate(date).toLocaleDateString('pl-PL',{weekday:'short'}).replace('.', '');}
function currentMonthPrefix(){return new Date().toISOString().slice(0,7);}
function compareRecord(a,b){if(!a)return 1;if(a.metric==='seconds'||b.metric==='seconds'){const byTime=(+b.value||0)-(+a.value||0);if(byTime)return byTime;}const byKg=(+b.kg||0)-(+a.kg||0);if(byKg)return byKg;return (+b.value||0)-(+a.value||0);}
function workoutEntries(){return data.workouts.flatMap(w=>(w.exercises||[]).flatMap(e=>(e.sets||[]).map(s=>({name:e.name,category:e.category||'Bez kategorii',kg:+s.kg||0,value:setMetricValue(s),metric:setMetricType(s),date:w.date,workoutId:w.id}))));}
function daysSinceLastWorkout(){const dates=data.workouts.map(w=>w.date).filter(Boolean).sort().reverse();if(!dates.length)return '--';return Math.max(0,Math.floor((parseIsoDate(todayIso())-parseIsoDate(dates[0]))/86400000));}
const trackedMuscles=['Plecy','Klata','Biceps','Triceps','Barki','Nogi','Brzuch'];
function muscleLabel(category){const value=normalizedText(category);if(value.includes('klat'))return 'Klata';return trackedMuscles.find(muscle=>value.includes(normalizedText(muscle)))||String(category||'').trim()||'Inne';}
function automaticWorkoutName(exercises=data.draft){const names=[];(exercises||[]).forEach(exercise=>{const name=muscleLabel(exercise.category);if(!names.includes(name))names.push(name);});return names.join(' ')||'Trening';}
function muscleRestDays(){const today=parseIsoDate(todayIso());return trackedMuscles.map(name=>{const dates=data.workouts.filter(workout=>(workout.exercises||[]).some(exercise=>muscleLabel(exercise.category)===name)).map(workout=>workout.date).filter(Boolean).sort().reverse();return {name,days:dates.length?Math.max(0,Math.floor((today-parseIsoDate(dates[0]))/86400000)):null};});}
function polishDays(days){if(days===null)return 'brak treningu';if(days===0)return 'dzisiaj';if(days===1)return '1 dzień';return `${days} dni`;}
function stats(){const weekStart=toIsoDate(startOfWeek(new Date()));const weekEnd=toIsoDate(addDays(parseIsoDate(weekStart),6));const records=workoutEntries();const best=Object.values(records.reduce((a,r)=>compareRecord(a[r.name],r)>0?{...a,[r.name]:r}:a,{})).sort((a,b)=>compareRecord(a,b));return {total:data.workouts.length,weekCount:data.workouts.filter(w=>w.date>=weekStart&&w.date<=weekEnd).length,monthCount:data.workouts.filter(w=>String(w.date||'').startsWith(currentMonthPrefix())).length,restDays:daysSinceLastWorkout(),volume:Math.round(records.reduce((s,r)=>s+(r.metric==='reps'?r.kg*r.value:0),0)/1000),records:best};}
function render(keepScroll=false){const previousScroll=keepScroll?[...document.querySelectorAll('.screen, .sheet-content')].map(element=>element.scrollTop):[];if(!user){root.innerHTML=sprite()+shell(login(),false);bindLogin();return;} if(isLoading){root.innerHTML=sprite()+shell('<div class="login"><div class="logo">🏋️</div><h1>Ładowanie danych...</h1><p>Przygotowujemy osobny widok tej osoby.</p></div>',false);return;} root.innerHTML=sprite()+shell((syncError?`<p class="error">${syncError}</p>`:'')+(catalogError?`<p class="error">${catalogError}</p>`:'')+(planning?builder():views[tab](user)),!planning); bind();ensureTicker();if(keepScroll)requestAnimationFrame(()=>{document.querySelectorAll('.screen, .sheet-content').forEach((element,index)=>{element.scrollTop=previousScroll[index]||0;});ensureTicker();});}
function shell(content,nav=true){return `<main class="phone"><section class="screen">${content}</section>${nav?navHtml():''}</main>`;}
function login(){const accounts=readAccounts();const selected=accounts.find(a=>a.id===loginAccountId);return `<div class="login"><div class="logo">🏋️</div><p class="eyebrow">Twój dziennik siłowni</p><h1>Kto teraz ćwiczy?</h1><p>Wybierz osobę i podaj hasło dostępu. Każdy profil ma własne treningi, historię i plany.</p>${accounts.length?`<div class="account-list">${accounts.map(a=>`<button class="account" data-id="${a.id}"><span class="avatar small">${escapeHtml(a.name[0])}</span><span>${escapeHtml(a.name)}</span></button>`).join('')}</div>`:'<p class="empty">Brak kont. Dodaj pierwszą osobę.</p>'}${selected?`<form id="login-account" class="new-account login-account"><b>Hasło dla: ${escapeHtml(selected.name)}</b><input id="login-password" name="password" type="password" autocomplete="current-password" placeholder="Hasło dostępu" required autofocus><button type="submit">Zaloguj</button></form>`:''}<form id="new-account" class="new-account"><input id="account-name" name="name" autocomplete="name" placeholder="Imię osoby" required><input id="account-password" name="password" type="password" autocomplete="current-password" placeholder="Hasło dostępu" required><button type="submit">Stwórz nowe konto</button></form>${loginError?`<p class="error">${loginError}</p>`:''}</div>`;}
const views={home:(u)=>{const s=stats();const recent=recentWorkouts().slice(0,3);return `<h1>Hej, ${escapeHtml((u.name||'Sportowcu').split(' ')[0])}</h1><button class="primary" id="start">${icon('play')} Zaplanuj trening</button>${statsHtml(s)}${muscleRestHtml()}<h2>Ostatnie treningi</h2>${recent.length?recent.map(workoutCard).join(''):'<p class="empty compact">Brak treningów z wczoraj i dzisiaj.</p>'}`},history:()=>historyView(),plan:()=>planView(),profile:(u)=>{const s=stats();const name=u.name||'Użytkownik';return `<h1>Profil</h1><div class="card profile"><div class="avatar">${escapeHtml(name[0])}</div><b>${escapeHtml(name)}</b></div>${statsHtml(s,'profile')}<h2>Rekordy osobiste</h2>${recordsByCategory(s.records)}<button class="secondary" id="logout">Zmień osobę</button>`}};

function weekLabel(start){const end=addDays(start,6);if(planWeekOffset===0)return 'Ten tydzień';return `${formatShortDate(toIsoDate(start))} – ${formatShortDate(toIsoDate(end))}`;}
function planEntry(date){const entry=data.plans?.[date];if(!entry)return null;if(typeof entry==='string')return {templateId:null,name:entry};return entry;}
function templateExerciseBlocks(exercises){const blocks=[];(Array.isArray(exercises)?exercises:[]).forEach(exercise=>{const name=exercise.name||'Ćwiczenie';const category=exercise.category||'Bez kategorii';const last=blocks[blocks.length-1];if(last&&last.name===name&&last.category===category){last.count+=1;last.sets.push(...(Array.isArray(exercise.sets)?exercise.sets:[]));}else{blocks.push({name,category,count:1,sets:[...(Array.isArray(exercise.sets)?exercise.sets:[])]});}});return blocks;}
function templateSummary(template){const blocks=templateExerciseBlocks(template.exercises);const series=blocks.reduce((sum,block)=>sum+block.count,0);return blocks.length===series?`${blocks.length} ćw.`:`${blocks.length} ćw. • ${series} serii`;}
function moveDraftExercise(from,to){if(from===to||from<0||to<0||from>=data.draft.length||to>=data.draft.length)return false;const [exercise]=data.draft.splice(from,1);data.draft.splice(to,0,exercise);return true;}
function recentWorkouts(){const today=todayIso();const yesterday=toIsoDate(addDays(parseIsoDate(today),-1));return data.workouts.filter(w=>w.date===today||w.date===yesterday);}
function templateDraftKey(){return JSON.stringify({name:(workoutName.trim()||'Mój trening'),exercises:data.draft.map(cloneTemplateExercise)});}
function clearTemplateSaveState(){templateNotice='';lastSavedTemplateKey='';}
function normalizedText(value){return String(value||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');}
function historyExerciseNames(){return [...new Set(data.workouts.flatMap(workout=>(workout.exercises||[]).map(exercise=>exercise.name).filter(Boolean)))].sort((a,b)=>a.localeCompare(b,'pl'));}
function filteredHistoryWorkouts(){const query=normalizedText(historyExerciseFilter);if(!query)return data.workouts;return data.workouts.filter(workout=>(workout.exercises||[]).some(exercise=>normalizedText(exercise.name).includes(query)));}
function historyView(){const names=historyExerciseNames();const workouts=filteredHistoryWorkouts();return `<h1>Historia</h1><label class="picker-label history-filter">Filtruj po nazwie ćwiczenia<select id="history-exercise-filter"><option value="">Wszystkie ćwiczenia</option>${names.map(name=>`<option value="${escapeHtml(name)}" ${name===historyExerciseFilter?'selected':''}>${escapeHtml(name)}</option>`).join('')}</select></label>${historyExerciseFilter?`<button class="secondary clear-history-filter" type="button">Wyczyść filtr</button>`:''}${workouts.length?workouts.map(workoutCard).join(''):'<p class="empty compact">Brak treningów z tym ćwiczeniem.</p>'}`;}
function loadTemplateToDraft(template){workoutName=template?.name||'Mój trening';data.draft=Array.isArray(template?.exercises)?template.exercises.map(cloneTemplateExercise):[];clearTemplateSaveState();}
function startBlankWorkout(){planning=true;editingTemplateId=null;editingWorkoutId=null;editingWorkoutDate='';editingWorkoutDuration=0;editingPlanDate='';planningPlanDate='';data.draft=[];workoutName='Mój trening';startedAt=0;restStartedAt=0;catalogSheetOpen=false;templateSheetOpen=false;clearTemplateSaveState();save();render();}
function startWorkoutFromTemplate(template){planning=true;editingTemplateId=null;editingWorkoutId=null;editingWorkoutDate='';editingWorkoutDuration=0;editingPlanDate='';planningPlanDate='';loadTemplateToDraft(template);startedAt=0;restStartedAt=0;catalogSheetOpen=false;templateSheetOpen=false;save();render();}
function scheduleWorkout(date){planning=true;editingTemplateId=null;editingWorkoutId=null;editingWorkoutDate='';editingWorkoutDuration=0;editingPlanDate='';planningPlanDate=date;data.draft=[];workoutName='Mój trening';startedAt=0;restStartedAt=0;catalogSheetOpen=false;templateSheetOpen=false;clearTemplateSaveState();save();render();}
function editPlannedWorkout(date){const entry=planEntry(date);if(!entry)return;planning=true;editingTemplateId=null;editingWorkoutId=null;editingWorkoutDate='';editingWorkoutDuration=0;editingPlanDate='';planningPlanDate=date;workoutName=entry.name||'Mój trening';data.draft=Array.isArray(entry.exercises)?entry.exercises.map(cloneTemplateExercise):[];startedAt=0;restStartedAt=0;catalogSheetOpen=false;templateSheetOpen=false;clearTemplateSaveState();save();render();}
function startPlannedWorkout(entry){planning=true;editingTemplateId=null;editingWorkoutId=null;editingWorkoutDate='';editingWorkoutDuration=0;editingPlanDate='';planningPlanDate='';workoutName=entry.name||'Mój trening';data.draft=Array.isArray(entry.exercises)?entry.exercises.map(cloneTemplateExercise):[];startedAt=0;restStartedAt=0;catalogSheetOpen=false;templateSheetOpen=false;clearTemplateSaveState();save();render();}
function editWorkout(workoutId){const workout=data.workouts.find(w=>String(w.id)===String(workoutId));if(!workout)return;planning=true;editingTemplateId=null;editingPlanDate='';editingWorkoutId=workout.id;editingWorkoutDate=workout.date||todayIso();editingWorkoutDuration=+workout.duration||0;workoutName=workout.name||'Mój trening';data.draft=Array.isArray(workout.exercises)?workout.exercises.map(cloneExercise):[];startedAt=0;restStartedAt=0;catalogSheetOpen=false;templateSheetOpen=false;save();render();}
function editTemplate(templateId, planDate=''){const template=(data.templates||[]).find(t=>String(t.id)===String(templateId));if(!template)return;planning=true;editingTemplateId=template.id;editingPlanDate=planDate;loadTemplateToDraft(template);startedAt=0;restStartedAt=0;catalogSheetOpen=false;templateSheetOpen=false;save();render();}
function editPlannedTemplate(date){const entry=planEntry(date);if(entry?.templateId)editTemplate(entry.templateId,date);}
function planView(){const start=addDays(startOfWeek(new Date()),planWeekOffset*7);const days=Array.from({length:7},(_,i)=>toIsoDate(addDays(start,i)));if(!days.includes(selectedPlanDate))selectedPlanDate=days[0];const selectedWorkouts=data.workouts.filter(w=>w.date===selectedPlanDate);const selectedPlan=planEntry(selectedPlanDate);const plannedTemplate=selectedPlan?.templateId?(data.templates||[]).find(t=>String(t.id)===String(selectedPlan.templateId)):null;const plannedSummary=plannedTemplate?templateSummary(plannedTemplate):(selectedPlan?.exercises?templateSummary({exercises:selectedPlan.exercises}):'');return `<h1>Plan treningowy</h1><div class="week"><button class="week-prev" type="button" aria-label="Poprzedni tydzień">${icon('left')}</button><b>${weekLabel(start)}</b><button class="week-next" type="button" aria-label="Następny tydzień">${icon('right')}</button></div><div class="days">${days.map(date=>`<button class="day ${date===selectedPlanDate?'active':''}" data-date="${date}" type="button"><span>${weekdayName(date)}</span><b>${parseIsoDate(date).getDate()}</b></button>`).join('')}</div><section class="selected-day"><p class="eyebrow">Wybrany dzień</p><h2>${formatDate(selectedPlanDate)}</h2>${selectedWorkouts.length?`<div class="plan-section"><h3>Treningi z historii</h3>${selectedWorkouts.map(w=>`<button class="card plan-workout" data-workout-id="${escapeHtml(String(w.id))}" type="button"><span><b>${escapeHtml(w.name||'Mój trening')}</b><small>${(w.exercises||[]).length} ćw. • ${formatDuration(w.duration||0)}</small></span><strong>Otwórz</strong></button>`).join('')}</div>`:'<p class="empty compact">Tego dnia nie ma zapisanego treningu.</p>'}${selectedPlan?`<div class="card planned-template"><span><b>${escapeHtml(selectedPlan.name||plannedTemplate?.name||'Szablon treningu')}</b><small>${plannedTemplate?'Zaplanowany szablon':'Zaplanowany trening'}${plannedSummary?` • ${plannedSummary}`:''}</small></span><div class="planned-actions"><button class="mini icon-only edit-plan-template" data-date="${selectedPlanDate}" type="button" aria-label="Edytuj zaplanowany trening">${icon('edit')}</button><button class="mini icon-only danger remove-plan" data-date="${selectedPlanDate}" type="button" aria-label="Usuń zaplanowany szablon">${icon('trash')}</button></div></div>`:`<div class="plan-actions"><button class="secondary" id="plan-add-template" type="button">Dodaj szablon treningu</button><button class="primary" id="plan-schedule-workout" type="button">${icon('play')} Zaplanuj trening</button></div>`}</section>${templateLibrary(false)}`;}

function statsHtml(s,context='training'){const firstValue=context==='profile'?s.total:s.weekCount;const firstLabel=context==='profile'?'Ilość treningów':'tydzień';return `<div class="stats"><div class="tile"><b>${firstValue}</b><span>${firstLabel}</span></div><div class="tile"><b>${s.monthCount}</b><span>miesiąc</span></div><div class="tile"><b>${s.restDays}</b><span>Rest days</span></div></div>`;}
function muscleRestHtml(){return `<section class="muscle-rest"><h2>Ostatni trening partii</h2><div class="card muscle-rest-grid">${muscleRestDays().map(item=>`<div><span>${escapeHtml(item.name)}</span><b>${polishDays(item.days)}</b></div>`).join('')}</div></section>`;}
function recordLabel(r){return r.metric==='seconds'?`${formatMetric(r.value,r.metric)} • ${r.kg} kg`:`${r.kg} kg × ${formatMetric(r.value,r.metric)}`;}
function recordCard(r){return `<div class="card row record-card"><span><b>${escapeHtml(r.name)}</b><small>${formatDate(r.date)}</small></span><strong>${recordLabel(r)}</strong></div>`;}
function recordsByCategory(records){const groups=[];(records||[]).forEach(record=>{const name=muscleLabel(record.category);let group=groups.find(item=>item.name===name);if(!group){group={name,records:[]};groups.push(group);}group.records.push(record);});return groups.length?groups.map(group=>{const expanded=expandedRecordCategories.has(group.name);return `<section class="record-group"><button class="card record-group-summary" data-record-category="${escapeHtml(group.name)}" type="button" aria-expanded="${expanded}"><span><b>${escapeHtml(group.name)}</b><small>${group.records.length} ${group.records.length===1?'rekord':'rekordów'}</small></span><span class="chevron">${expanded?'⌃':'⌄'}</span></button>${expanded?`<div class="record-group-details">${group.records.map(recordCard).join('')}</div>`:''}</section>`;}).join(''):'<p class="empty compact">Brak zapisanych rekordów.</p>';}
function exerciseRecord(name){return stats().records.find(r=>r.name===name);}
function recentExerciseRecords(name){return data.workouts.filter(w=>(w.exercises||[]).some(e=>e.name===name)).slice(0,5).map(w=>{const best=(w.exercises||[]).filter(e=>e.name===name).flatMap(e=>(e.sets||[]).map(s=>({name:e.name,category:e.category,kg:+s.kg||0,value:setMetricValue(s),metric:setMetricType(s),date:w.date}))).reduce((best,item)=>compareRecord(best,item)>0?item:best,null);return best?`${formatDate(w.date)}: ${recordLabel(best)}`:'';}).filter(Boolean);}
function exerciseDetails(exercise){if(!exercise?.description&&!exercise?.imageUrl)return '<small>Brak opisu i zdjęcia tego ćwiczenia.</small>';return `${exercise.description?`<p>${escapeHtml(exercise.description)}</p>`:''}${exercise.imageUrl?`<img class="exercise-photo" src="${escapeHtml(exercise.imageUrl)}" alt="${escapeHtml(exercise.name||'Zdjęcie ćwiczenia')}" loading="lazy" referrerpolicy="no-referrer">`:''}`;}
function recordHint(name){const best=exerciseRecord(name);const recent=recentExerciseRecords(name);return `<div class="record-popover"><b>Rekord: ${best?recordLabel(best):'brak'}</b>${best?`<small>${formatDate(best.date)}</small>`:''}${recent.length?`<ul>${recent.map(item=>`<li>${escapeHtml(item)}</li>`).join('')}</ul>`:'<small>Brak ostatnich treningów z tym ćwiczeniem.</small>'}${exerciseDetails(catalog.find(item=>item.name===name))}</div>`;}
function groupedExercises(exercises){const groups=[];(Array.isArray(exercises)?exercises:[]).forEach(exercise=>{const key=`${exercise.name||'Ćwiczenie'}__${exercise.category||'Bez kategorii'}`;let group=groups.find(item=>item.key===key);if(!group){group={key,name:exercise.name||'Ćwiczenie',category:exercise.category||'Bez kategorii',sets:[]};groups.push(group);}group.sets.push(...(Array.isArray(exercise.sets)?exercise.sets:[]));});return groups;}
function workoutCard(w){const id=String(w.id);const exercises=Array.isArray(w.exercises)?w.exercises:[];const grouped=groupedExercises(exercises);const volume=exercises.flatMap(e=>Array.isArray(e.sets)?e.sets:[]).reduce((s,x)=>s+(setMetricType(x)==='reps'?(+x.kg||0)*setMetricValue(x):0),0);const expanded=expandedWorkouts.has(id);const details=expanded?`<div class="workout-details">${grouped.length?grouped.map(workoutExerciseDetails).join(''):'<p class="empty compact">Brak zapisanych ćwiczeń dla tego treningu.</p>'}</div>`:'';return `<div class="card workout-card ${expanded?'expanded':''}"><div class="workout-card-head"><button class="workout-summary" data-workout-id="${escapeHtml(id)}" type="button" aria-expanded="${expanded}"><span><b>${escapeHtml(w.name||'Mój trening')}</b><small>${formatDate(w.date)}</small></span><span class="chevron">${expanded?'⌃':'⌄'}</span></button><button class="edit-workout" data-workout-id="${escapeHtml(id)}" type="button" aria-label="Edytuj trening ${escapeHtml(w.name||'Mój trening')}">${icon('edit')}</button><button class="delete-workout" data-workout-id="${escapeHtml(id)}" type="button" aria-label="Usuń trening ${escapeHtml(w.name||'Mój trening')}">${icon('x')}</button></div><p class="muted">${icon('pulse')} ${grouped.length} ćw. ${icon('trend')} ${volume} kg ${icon('clock')} ${formatDuration(w.duration||0)}</p>${details}</div>`;}
function workoutExerciseDetails(exercise){const sets=Array.isArray(exercise.sets)?exercise.sets:[];return `<div class="history-exercise"><div><b>${escapeHtml(exercise.name||'Ćwiczenie')}</b><span>${escapeHtml(exercise.category||'Bez kategorii')}</span></div><ol>${sets.map((set,index)=>`<li><span>Seria ${index+1}</span><strong>${+set.kg||0} kg × ${formatSetMetric(set)}</strong></li>`).join('')||'<li><span>Brak serii</span></li>'}</ol></div>`;}
function templateCard(template){const blocks=templateExerciseBlocks(template.exercises);return `<div class="card template-card"><div><b>${escapeHtml(template.name||'Mój trening')}</b><small>${templateSummary(template)}</small></div>${blocks.length?`<ul>${blocks.map(block=>`<li><span>${escapeHtml(block.name)}${block.count>1?` - ${block.count} serie`:''}</span><em>${escapeHtml(block.category)}</em></li>`).join('')}</ul>`:'<p class="empty compact">Brak ćwiczeń w szablonie.</p>'}<div class="template-actions"><button class="mini load-template" data-template-id="${escapeHtml(String(template.id))}" type="button">Wczytaj</button><button class="mini icon-only edit-template" data-template-id="${escapeHtml(String(template.id))}" type="button" aria-label="Edytuj szablon ${escapeHtml(template.name||'Mój trening')}">${icon('edit')}</button><button class="mini icon-only danger delete-template" data-template-id="${escapeHtml(String(template.id))}" type="button" aria-label="Usuń szablon ${escapeHtml(template.name||'Mój trening')}">${icon('trash')}</button></div></div>`;}
function exerciseCatalogForm(){return `<p class="hint">${icon('info')} Dodaj nowe ćwiczenie do wspólnej listy aplikacji.</p><form id="custom-exercise" class="exercise-form"><label>Nazwa ćwiczenia<input id="exercise-name" placeholder="np. Pompki" required></label><label>Kategoria<input id="exercise-category" list="category-list" placeholder="np. Klatka piersiowa" required></label><datalist id="category-list">${[...new Set(catalog.map(e=>e.category).sort((a,b)=>a.localeCompare(b,'pl')))].map(c=>`<option value="${escapeHtml(c)}"></option>`).join('')}</datalist><label>Opis ćwiczenia<textarea id="exercise-description" placeholder="Technika, wskazówki..."></textarea></label><label>Link URL do zdjęcia<input id="exercise-image-url" type="url" placeholder="https://..."></label><button type="submit">${icon('plus')} Dodaj do wspólnej listy</button></form>`;}
function templateLibrary(showButton=true){const templates=data.templates||[];const content=templates.length?templates.map(templateCard).join(''):'<p class="empty compact">Brak zapisanych szablonów.</p>';return `${showButton?'<div class="template-library"><button class="secondary templates-open" id="open-templates" type="button">Szablony treningów</button></div>':''}${templateSheetOpen?`<div class="sheet-backdrop" data-close-templates="true"><section class="bottom-sheet" role="dialog" aria-modal="true" aria-labelledby="templates-title"><div class="sheet-handle" aria-hidden="true"></div><div class="sheet-header"><h2 id="templates-title">Szablony treningów</h2><button class="sheet-close" data-close-templates="true" type="button" aria-label="Zamknij bazę szablonów">${icon('x')}</button></div><div class="sheet-content">${exerciseCatalogForm()}${content}</div></section></div>`:''}`;}
function normalizeSet(set){const metric=set?.metric==='seconds'||set?.unit==='seconds'||set?.type==='seconds'?'seconds':'reps';const reps=Number.isFinite(+set?.reps)?Math.max(0,+set.reps):0;const seconds=Number.isFinite(+set?.seconds)?Math.max(0,+set.seconds):reps;return {kg:+set?.kg||0,reps,seconds,metric};}
function cloneExercise(exercise){return {name:exercise.name,category:exercise.category,description:exercise.description||'',imageUrl:exercise.imageUrl||'',sets:(Array.isArray(exercise.sets)?exercise.sets:[]).map(normalizeSet),completed:!!exercise.completed};}
function setMetricType(set){return set?.metric==='seconds'?'seconds':'reps';}
function setMetricValue(set){return setMetricType(set)==='seconds'?(+set.seconds||+set.reps||0):(+set.reps||0);}
function formatMetric(value,metric){return metric==='seconds'?`${+value||0}s`:`${+value||0} powt.`;}
function formatSetMetric(set){return formatMetric(setMetricValue(set),setMetricType(set));}
function cloneTemplateExercise(exercise){return {...cloneExercise(exercise),completed:false};}
function formatDuration(seconds){
 const total=Math.max(0,Math.floor(+seconds||0));
 const hours=Math.floor(total/3600);
 const minutes=Math.floor((total%3600)/60);
 const remainingSeconds=total%60;
 if(hours){
  return [hours+'h',minutes?minutes+'min':'',remainingSeconds?remainingSeconds+'s':''].filter(Boolean).join(' ');
 }
 if(minutes){
  return [minutes+'min',remainingSeconds?remainingSeconds+'s':''].filter(Boolean).join(' ');
 }
 return total+'s';
}
function formatSeconds(seconds){return formatDuration(seconds);}
function updateTimers(){if(!startedAt)return;const main=$('#timer');if(main)main.textContent=formatSeconds((Date.now()-startedAt)/1000);document.querySelectorAll('.rest-timer').forEach(rest=>{rest.textContent=restStartedAt?formatSeconds((Date.now()-restStartedAt)/1000):'--';});}
function stopTicker(){clearInterval(timer);timer=null;}
function startTicker(){stopTicker();timer=setInterval(updateTimers,1000);updateTimers();}
function ensureTicker(){if(startedAt){if(!timer)startTicker();else updateTimers();}}
function sortedCatalog(){return [...catalog].sort((a,b)=>a.category.localeCompare(b.category,'pl')||a.name.localeCompare(b.name,'pl'));}
function catalogOptions(){let current='';return sortedCatalog().map(e=>{const group=e.category!==current?`${current?'</optgroup>':''}<optgroup label="${escapeHtml(e.category)}">`:'';current=e.category;return `${group}<option value="${e.id}">${escapeHtml(e.name)}</option>`;}).join('')+(current?'</optgroup>':'');}
function restPanel(){return startedAt?`<div class="rest-panel sticky-rest"><span>Przerwa po ostatnim wykonanym ćwiczeniu</span><b class="rest-timer">${restStartedAt?formatSeconds((Date.now()-restStartedAt)/1000):'--'}</b></div>`:'';}
function draftBlocks(){return data.draft.map((e,i)=>{const set=e.sets[0]||normalizeSet({});const metric=setMetricType(set);const hintOpen=activeRecordHint===String(i);return `<div class="card exercise-block ${e.completed?'completed':''}" draggable="true" data-draft-index="${i}"><div class="row exercise-title"><button class="drag-handle" type="button" draggable="true" aria-label="Przesuń ćwiczenie">☰</button><span><b>${escapeHtml(e.name)}</b><span class="badge">${escapeHtml(e.category||'Bez kategorii')}</span></span><div class="exercise-actions"><span class="record-info-wrap"><button class="mini icon-only record-info" data-i="${i}" type="button" aria-label="Pokaż rekordy ćwiczenia">${icon('info')}</button>${hintOpen?recordHint(e.name):''}</span><button class="mini icon-only move-draft" data-i="${i}" data-dir="-1" type="button" aria-label="Przesuń wyżej">↑</button><button class="mini icon-only move-draft" data-i="${i}" data-dir="1" type="button" aria-label="Przesuń niżej">↓</button>${startedAt?`<button class="mini icon-only complete-exercise completion-circle ${e.completed?'done':''}" data-i="${i}" type="button" aria-label="${e.completed?'Odznacz ćwiczenie jako wykonane':'Oznacz ćwiczenie jako wykonane'}"><span aria-hidden="true">${e.completed?'✓':''}</span></button>`:''}<button class="mini icon-only duplicate-exercise" data-i="${i}" type="button" aria-label="Duplikuj ćwiczenie">${icon('copy')}</button><button class="mini icon-only danger remove-draft-exercise" data-i="${i}" type="button" aria-label="Usuń ćwiczenie">${icon('trash')}</button></div></div><div class="set"><input data-i="${i}" data-k="kg" type="number" value="${set.kg}"> kg <input data-i="${i}" data-k="${metric}" type="number" min="0" value="${setMetricValue(set)}"> ${metric==='seconds'?'sek.':'powt.'}<button class="mini set-metric-toggle" data-i="${i}" type="button">${metric==='seconds'?'Na powtórzenia':'Na sekundy'}</button></div></div>`;}).join('');}
function catalogList(){const list=sortedCatalog().map(e=>{const infoOpen=activeExerciseInfo===e.id;const editing=editingCatalogId===e.id;return `<div class="catalog-entry"><div class="sheet-item catalog-item"><span><b>${escapeHtml(e.name)}</b><br><span>${escapeHtml(e.category)}</span></span><div class="catalog-actions"><button class="mini icon-only exercise-info" data-id="${escapeHtml(e.id)}" type="button" aria-label="Pokaż opis ćwiczenia">${icon('info')}</button><button class="mini icon-only edit-catalog-exercise" data-id="${escapeHtml(e.id)}" type="button" aria-label="Edytuj ćwiczenie">${icon('edit')}</button><button class="mini icon-only danger delete-catalog-exercise" data-id="${escapeHtml(e.id)}" type="button" aria-label="Usuń ćwiczenie ze wspólnej listy">${icon('trash')}</button></div></div>${infoOpen?`<div class="exercise-details">${exerciseDetails(e)}</div>`:''}${editing?`<form class="exercise-form edit-catalog-form" data-id="${escapeHtml(e.id)}"><label>Nazwa<input name="name" value="${escapeHtml(e.name)}" required></label><label>Kategoria<input name="category" value="${escapeHtml(e.category)}" required></label><label>Opis<textarea name="description">${escapeHtml(e.description||'')}</textarea></label><label>Link URL do zdjęcia<input name="imageUrl" type="url" value="${escapeHtml(e.imageUrl||'')}" placeholder="https://..."></label><button type="submit">${icon('save')} Zapisz zmiany</button></form>`:''}</div>`;}).join('');return `<div class="catalog-list"><button class="secondary catalog-open" id="open-catalog" type="button">Lista ćwiczeń w aplikacji</button></div>${catalogSheetOpen?`<div class="sheet-backdrop" data-close-catalog="true"><section class="bottom-sheet" role="dialog" aria-modal="true" aria-labelledby="catalog-title"><div class="sheet-handle" aria-hidden="true"></div><div class="sheet-header"><h2 id="catalog-title">Lista ćwiczeń w aplikacji</h2><button class="sheet-close" data-close-catalog="true" type="button" aria-label="Zamknij listę ćwiczeń">${icon('x')}</button></div><div class="sheet-content">${list}</div></section></div>`:''}`;}
function workoutDurationEditor(){const total=Math.max(0,Math.floor(+editingWorkoutDuration||0));const h=Math.floor(total/3600);const m=Math.floor((total%3600)/60);const sec=total%60;return `<div class="workout-tools workout-edit-tools"><label class="workout-name">Data treningu<input id="workout-date" type="date" value="${escapeHtml(editingWorkoutDate)}"></label><div class="workout-name duration-editor">Czas treningu<div class="duration-fields"><label><input id="workout-duration-hours" type="number" min="0" value="${h}"> godz.</label><label><input id="workout-duration-minutes" type="number" min="0" max="59" value="${m}"> min</label><label><input id="workout-duration-seconds" type="number" min="0" max="59" value="${sec}"> sek.</label></div><small class="duration-preview">${formatDuration(editingWorkoutDuration)}</small></div></div>`;}
function builder(){const isTemplateEdit=editingTemplateId!==null;const isWorkoutEdit=editingWorkoutId!==null;const isPlanSchedule=!!planningPlanDate;const nameControl=isTemplateEdit?`<label class="workout-name">Nazwa szablonu<input id="workout-name" value="${escapeHtml(workoutName)}" placeholder="Nazwa szablonu"></label>`:`<div class="automatic-name"><small>Automatyczna nazwa treningu</small><b>${escapeHtml(automaticWorkoutName())}</b></div>`;return `<div class="top"><button id="close">${icon('x')}</button><span id="timer">${isWorkoutEdit?'Edycja treningu':(isTemplateEdit?'Edycja szablonu':(isPlanSchedule?`Plan na ${formatDate(planningPlanDate)}`:(startedAt?formatSeconds((Date.now()-startedAt)/1000):'Planowanie')))}</span><button id="begin">${isWorkoutEdit||isTemplateEdit||isPlanSchedule?'Zapisz':(startedAt?'Zakończ':'Rozpocznij')}</button></div>${restPanel()}${isWorkoutEdit?workoutDurationEditor():''}${isTemplateEdit?`<p class="hint">Edytujesz szablon${editingPlanDate?` zaplanowany na ${formatDate(editingPlanDate)}`:''}. Zmiany będą używane przy kolejnych treningach z tego szablonu.</p>`:''}<div class="workout-tools">${nameControl}${isTemplateEdit?'':`<button class="ghost compact-save" id="save-template" type="button" ${data.draft.length&&!templateSaveInProgress?'':'disabled'}>${icon('save')} ${templateSaveInProgress?'Zapisywanie...':'Szablon'}</button>`}</div>${templateNotice?`<p class="success" role="status">${templateNotice}</p>`:''}${!isTemplateEdit&&data.templates&&data.templates.length?`<label class="picker-label">Wczytaj szablon<select id="template-picker"><option value="">Wybierz szablon</option>${data.templates.map(t=>`<option value="${t.id}">${escapeHtml(t.name)}</option>`).join('')}</select></label>`:''}${data.draft.length?'':'<p class="empty">Dodaj ćwiczenia, aby zaplanować trening</p>'}${draftBlocks()}<label class="picker-label exercise-picker-label">Dodaj ćwiczenie do treningu<select id="exercise-picker"><option value="">Wybierz ćwiczenie</option>${catalogOptions()}</select></label>${templateLibrary()}${catalogList()}`;}
function navHtml(){return `<nav>${[['home','home','Trening'],['history','history','Historia'],['plan','plan','Plan'],['profile','profile','Profil']].map(([id,ic,l])=>`<button class="nav ${tab===id?'on':''}" data-tab="${id}"><span>${navIcon(ic)}</span><small>${l}</small></button>`).join('')}</nav>`;}
function bindLogin(){document.querySelectorAll('.account').forEach(b=>b.onclick=()=>{loginAccountId=b.dataset.id;loginError='';render();}); const loginForm=$('#login-account'); if(loginForm)loginForm.onsubmit=async(event)=>{event.preventDefault();const account=readAccounts().find(a=>a.id===loginAccountId);const password=$('#login-password')?.value||'';if(!account)return;try{await authenticate(password);loginAccountId='';selectAccount(account);}catch(error){loginError=error.message;render();}}; const form=$('#new-account'); if(form)form.onsubmit=async(event)=>{event.preventDefault();const input=$('#account-name');const passwordInput=$('#account-password');const name=input.value.trim();const password=passwordInput.value;if(!name){loginError='Podaj imię osoby.';render();return;}if(!password){loginError='Podaj hasło dostępu.';render();return;}try{await authenticate(password);}catch(error){loginError=error.message;render();return;}const account={id:accountId(name),name};await saveAccount(account);data=emptyData();selectAccount(account);};}

function bindDraftReorder(){
 document.querySelectorAll('.exercise-block').forEach(block=>{
  const handle=block.querySelector('.drag-handle');
  block.addEventListener('dragstart',event=>{if(!event.target.closest('.drag-handle')){event.preventDefault();return;}draggedDraftIndex=+block.dataset.draftIndex;block.classList.add('dragging');event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',String(draggedDraftIndex));});
  block.addEventListener('dragend',()=>{draggedDraftIndex=null;block.classList.remove('dragging');document.querySelectorAll('.exercise-block.drag-over').forEach(el=>el.classList.remove('drag-over'));});
  block.addEventListener('dragover',event=>{event.preventDefault();block.classList.add('drag-over');});
  block.addEventListener('dragleave',()=>block.classList.remove('drag-over'));
  block.addEventListener('drop',async event=>{event.preventDefault();const target=+block.dataset.draftIndex;const from=Number.isInteger(draggedDraftIndex)?draggedDraftIndex:+event.dataTransfer.getData('text/plain');draggedDraftIndex=null;moveDraftExercise(from,target);await save();render(true);});
  if(!handle)return;
  handle.addEventListener('touchstart',event=>{draggedDraftIndex=+block.dataset.draftIndex;block.classList.add('dragging');event.preventDefault();},{passive:false});
  handle.addEventListener('touchmove',event=>{const touch=event.touches[0];const target=document.elementFromPoint(touch.clientX,touch.clientY)?.closest('.exercise-block');document.querySelectorAll('.exercise-block.drag-over').forEach(el=>el.classList.remove('drag-over'));if(target&&target!==block)target.classList.add('drag-over');event.preventDefault();},{passive:false});
  handle.addEventListener('touchend',async event=>{const touch=event.changedTouches[0];const target=document.elementFromPoint(touch.clientX,touch.clientY)?.closest('.exercise-block');const from=draggedDraftIndex;draggedDraftIndex=null;block.classList.remove('dragging');document.querySelectorAll('.exercise-block.drag-over').forEach(el=>el.classList.remove('drag-over'));if(target){moveDraftExercise(from,+target.dataset.draftIndex);await save();render(true);}event.preventDefault();});
 });
}

